def search_tako(query, workspace_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        if dt is None:
            dt = _now()
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return _now().isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _mk_id(prefix):
        # Deterministic-enough, collision-resistant offline id
        h = hashlib.sha256((prefix + "|" + _iso() + "|" + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}{h}"

    def _resolve_active_key_for_workspace(ws_id, workspaces, api_keys):
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace not found", workspace_id=ws_id)
        if ws.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=ws_id, status=ws.get("status"))
        keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"]
        if not keys:
            return ws, None, _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=ws_id)
        # pick most recently used, then created
        def _k_sort(k):
            lu = _parse_dt(k.get("last_used_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            ca = _parse_dt(k.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (lu, ca, k.get("id") or "")
        keys.sort(key=_k_sort, reverse=True)
        return ws, keys[0], None

    def _touch_key(api_keys, key_id):
        now = _iso()
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                return True
        return False

    def _parse_cursor(cur):
        # Cursor is opaque; accept any non-empty string.
        # If it decodes to our format, use it; otherwise treat as "start from beginning".
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("v") == 1:
                before = obj.get("before")
                rid = obj.get("id")
                if isinstance(before, str) and isinstance(rid, str) and _parse_dt(before) is not None:
                    return {"before": before, "id": rid}
        except Exception:
            pass
        # Unknown cursor formats are tolerated (opaque contract).
        return None

    def _make_cursor(last_created_at, last_id):
        payload = {"v": 1, "before": last_created_at, "id": last_id}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _record_run(tool_runs, ws_id, key_id, req_json, status, response_json=None, error_code=None, error_message=None, meter_units=0):
        now = _iso()
        run_id = _mk_id("tako_run_")
        row = {
            "id": run_id,
            "workspace_id": ws_id,
            "api_key_id": key_id,
            "tool_name": "search_tako",
            "request_json": req_json if isinstance(req_json, dict) else {},
            "uploaded_file_id": None,
            "dataset_id": None,
            "status": status,
            "started_at": now,
            "ended_at": now,
            "error_code": error_code,
            "error_message": error_message,
            "response_json": response_json,
            "visualization_kind": None,
            "visualization_artifact": None,
            "meter_units": int(meter_units) if isinstance(meter_units, int) and meter_units >= 0 else 0,
            "created_at": now,
            "updated_at": now,
        }
        tool_runs.append(row)
        return row

    t0 = time.time()

    # Validation
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer when provided")
        if limit < 0:
            return _err("VALIDATION_ERROR", "limit must be >= 0")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    # Load data
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    uploaded_files = _load("uploaded_files.json")
    datasets = _load("datasets.json")
    tool_runs = _load("tool_runs.json")

    # Resolve auth/context for THIS workspace (no "pick any" behavior)
    ws, key, auth_err = _resolve_active_key_for_workspace(workspace_id, workspaces, api_keys)
    if auth_err:
        # Must still record invocation? Business rule says every tool invocation must create tool_runs row,
        # but auth failures cannot attribute to a revoked/missing key; do not fabricate. Return error.
        return auth_err

    # Touch key last_used_at
    _touch_key(api_keys, key.get("id"))

    # Pagination
    lim = 50 if limit is None else limit
    curinfo = _parse_cursor(cursor)
    if isinstance(curinfo, dict) and curinfo.get("error"):
        # _parse_cursor can only return error dict for empty/bad type; already validated, but keep safe.
        return curinfo

    q = query.strip().lower()

    # Collect matches within workspace
    results = []

    def _add(kind, row, created_at):
        results.append({"kind": kind, "id": row.get("id"), "created_at": created_at, "object": row})

    for f in uploaded_files:
        if not isinstance(f, dict):
            continue
        if f.get("workspace_id") != workspace_id:
            continue
        hay = " ".join([
            str(f.get("id") or ""),
            str(f.get("original_filename") or ""),
            str(f.get("content_type") or ""),
            str(f.get("sha256_hex") or ""),
            str(f.get("status") or ""),
            str(f.get("error_message") or ""),
        ]).lower()
        if q in hay:
            _add("uploaded_file", f, f.get("created_at") or f.get("updated_at") or "")

    for d in datasets:
        if not isinstance(d, dict):
            continue
        if d.get("workspace_id") != workspace_id:
            continue
        hay = " ".join([
            str(d.get("id") or ""),
            str(d.get("format") or ""),
            str(d.get("status") or ""),
            str(d.get("payload_sha256_hex") or ""),
        ]).lower()
        if q in hay:
            _add("dataset", d, d.get("created_at") or d.get("updated_at") or "")

    for r in tool_runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        hay = " ".join([
            str(r.get("id") or ""),
            str(r.get("tool_name") or ""),
            str(r.get("status") or ""),
            str(r.get("error_code") or ""),
            str(r.get("error_message") or ""),
        ]).lower()
        if q in hay:
            _add("tool_run", r, r.get("created_at") or r.get("updated_at") or "")

    # Sort newest first by created_at then id
    def _sort_key(item):
        dt = _parse_dt(item.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, str(item.get("id") or ""))

    results.sort(key=_sort_key, reverse=True)

    # Apply cursor (if our own format)
    if isinstance(curinfo, dict) and "before" in curinfo:
        before_dt = _parse_dt(curinfo["before"])
        before_id = curinfo["id"]
        if before_dt is not None:
            filtered = []
            for it in results:
                it_dt = _parse_dt(it.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                it_id = str(it.get("id") or "")
                # include strictly older than cursor point; if same timestamp, use id tiebreak
                if it_dt < before_dt or (it_dt == before_dt and it_id < before_id):
                    filtered.append(it)
            results = filtered

    total = len(results)
    page = results[:lim] if lim is not None else results
    has_more = total > (len(page))
    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = last.get("created_at") or _iso()
        last_id = str(last.get("id") or "")
        if not isinstance(last_dt, str) or _parse_dt(last_dt) is None:
            last_dt = _iso()
        next_cursor = _make_cursor(last_dt, last_id)

    response_payload = {
        "query": query,
        "results": page,
        "total": total,
        "limit": lim,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

    # Record tool run (must always happen for successful invocation)
    run_row = _record_run(
        tool_runs=tool_runs,
        ws_id=workspace_id,
        key_id=key.get("id"),
        req_json={"query": query, "workspace_id": workspace_id, "limit": limit, "cursor": cursor},
        status="succeeded",
        response_json=response_payload,
        meter_units=0,
    )

    # Persist
    _save("api_keys.json", api_keys)
    _save("tool_runs.json", tool_runs)

    run_row["latency_ms"] = int((time.time() - t0) * 1000)
    return {"tool_run": run_row, "response": response_payload}

def upload_file_to_visualize(workspace_id, filename, file_base64, content_type=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        if dt is None:
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _new_id(prefix, existing_ids):
        ts = int(_now().timestamp() * 1000)
        for _ in range(50):
            rid = f"{prefix}_{ts:x}{random.getrandbits(48):012x}"
            if rid not in existing_ids:
                return rid
        rid = f"{prefix}_{ts:x}{hashlib.sha256(str(ts).encode()).hexdigest()[:12]}"
        if rid not in existing_ids:
            return rid
        return f"{prefix}_{ts:x}{random.getrandbits(64):016x}"

    def _resolve_auth(workspace_id, api_keys, workspaces):
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            return None, _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        if ws.get("status") != "active":
            return None, _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=workspace_id, status=ws.get("status"))
        candidates = [k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=workspace_id)
        def _k_sort(k):
            lu = _parse_dt(k.get("last_used_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            ca = _parse_dt(k.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (lu, ca)
        candidates.sort(key=_k_sort, reverse=True)
        return {"workspace": ws, "api_key": candidates[0]}, None

    def _touch_key_last_used(api_keys, key_id):
        nowiso = _iso()
        for k in api_keys:
            if k.get("id") == key_id:
                k["last_used_at"] = nowiso
                k["updated_at"] = nowiso
                return True
        return False

    def _retained_storage_bytes_for_workspace(workspace_id, uploaded_files, tool_runs):
        total = 0
        for f in uploaded_files:
            if not isinstance(f, dict):
                continue
            if f.get("workspace_id") != workspace_id:
                continue
            if f.get("status") == "deleted":
                continue
            sb = f.get("size_bytes")
            if isinstance(sb, int) and sb >= 0:
                total += sb
        for r in tool_runs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            art = r.get("visualization_artifact")
            if isinstance(art, dict):
                b = art.get("bytes")
                if isinstance(b, int) and b >= 0:
                    total += b
        return total

    t_start = time.time()

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(filename, str) or not filename.strip():
        return _err("VALIDATION_ERROR", "filename must be a non-empty string")
    if not isinstance(file_base64, str) or not file_base64.strip():
        return _err("VALIDATION_ERROR", "file_base64 must be a non-empty string")
    if content_type is not None:
        if not isinstance(content_type, str) or not content_type.strip():
            return _err("VALIDATION_ERROR", "content_type must be a non-empty string when provided")
        if not re.fullmatch(r"[A-Za-z0-9!#$&^_.+-]+/[A-Za-z0-9!#$&^_.+-]+", content_type.strip()):
            return _err("VALIDATION_ERROR", "content_type is invalid")
        content_type = content_type.strip()

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tool_runs = _load("tool_runs.json")
    uploaded_files = _load("uploaded_files.json")

    auth, auth_err = _resolve_auth(workspace_id.strip(), api_keys, workspaces)
    if auth_err:
        return auth_err
    ws = auth["workspace"]
    key = auth["api_key"]

    # Create tool_run row first (queued -> running -> succeeded/failed)
    run_id = _new_id("tako_run", {r.get("id") for r in tool_runs if isinstance(r, dict)})
    nowiso = _iso()
    run = {
        "id": run_id,
        "workspace_id": ws.get("id"),
        "api_key_id": key.get("id"),
        "tool_name": "upload_file_to_visualize",
        "request_json": {"workspace_id": workspace_id, "filename": filename, "content_type": content_type, "file_base64": file_base64},
        "uploaded_file_id": None,
        "dataset_id": None,
        "status": "queued",
        "started_at": None,
        "ended_at": None,
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "visualization_kind": None,
        "visualization_artifact": None,
        "meter_units": 0,
        "created_at": nowiso,
        "updated_at": nowiso,
    }
    tool_runs.append(run)
    run["status"] = "running"
    run["started_at"] = nowiso
    run["updated_at"] = nowiso

    # Decode base64
    try:
        raw = base64.b64decode(file_base64.encode("utf-8"), validate=False)
    except Exception:
        endiso = _iso()
        run["status"] = "failed"
        run["ended_at"] = endiso
        run["error_code"] = "VALIDATION_ERROR"
        run["error_message"] = "file_base64 could not be decoded"
        run["updated_at"] = endiso
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return _err("VALIDATION_ERROR", "file_base64 could not be decoded")

    size_bytes = len(raw)
    sha256_hex = hashlib.sha256(raw).hexdigest()

    # Enforce quotas: max files and storage bytes
    non_deleted_files = [f for f in uploaded_files if isinstance(f, dict) and f.get("workspace_id") == ws.get("id") and f.get("status") != "deleted"]
    if isinstance(ws.get("quota_max_files"), int) and ws.get("quota_max_files") >= 0:
        if len(non_deleted_files) >= ws.get("quota_max_files"):
            endiso = _iso()
            run["status"] = "failed"
            run["ended_at"] = endiso
            run["error_code"] = "QUOTA_EXCEEDED"
            run["error_message"] = "Workspace file quota exceeded (quota_max_files)"
            run["updated_at"] = endiso
            _touch_key_last_used(api_keys, key.get("id"))
            _save("tool_runs.json", tool_runs)
            _save("api_keys.json", api_keys)
            return _err("QUOTA_EXCEEDED", "Workspace file quota exceeded", rule="quota_max_files", quota=ws.get("quota_max_files"))

    retained = _retained_storage_bytes_for_workspace(ws.get("id"), uploaded_files, tool_runs)
    max_bytes = ws.get("quota_max_storage_bytes")
    if isinstance(max_bytes, int) and max_bytes >= 0:
        if retained + size_bytes > max_bytes:
            endiso = _iso()
            run["status"] = "failed"
            run["ended_at"] = endiso
            run["error_code"] = "QUOTA_EXCEEDED"
            run["error_message"] = "Workspace storage quota exceeded (quota_max_storage_bytes)"
            run["updated_at"] = endiso
            _touch_key_last_used(api_keys, key.get("id"))
            _save("tool_runs.json", tool_runs)
            _save("api_keys.json", api_keys)
            return _err("QUOTA_EXCEEDED", "Workspace storage quota exceeded", rule="quota_max_storage_bytes", quota=max_bytes, retained_bytes=retained, attempted_add_bytes=size_bytes)

    # Enforce dedup unique(workspace_id, sha256_hex, size_bytes) where status != 'deleted'
    existing = next((f for f in uploaded_files if isinstance(f, dict) and f.get("workspace_id") == ws.get("id")
                     and f.get("status") != "deleted" and f.get("sha256_hex") == sha256_hex and f.get("size_bytes") == size_bytes), None)
    if existing:
        # idempotent-ish: return existing file_id, still record run as succeeded
        endiso = _iso()
        run["status"] = "succeeded"
        run["ended_at"] = endiso
        run["uploaded_file_id"] = existing.get("id")
        run["response_json"] = {"file_id": existing.get("id")}
        run["updated_at"] = endiso
        run["meter_units"] = 0
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return {"file_id": existing.get("id")}

    # Persist blob to local storage
    storage_provider = "local"
    storage_bucket = "tako_local"
    blob_dir = os.path.join(_DB, "blobs")
    try:
        os.makedirs(blob_dir, exist_ok=True)
    except Exception:
        endiso = _iso()
        run["status"] = "failed"
        run["ended_at"] = endiso
        run["error_code"] = "CONFLICT"
        run["error_message"] = "Could not initialize local blob storage"
        run["updated_at"] = endiso
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return _err("CONFLICT", "Could not initialize local blob storage")

    file_id = _new_id("tako_file", {f.get("id") for f in uploaded_files if isinstance(f, dict)})
    storage_key = f"{ws.get('id')}/{file_id}/{sha256_hex}"
    blob_path = os.path.join(blob_dir, re.sub(r"[^A-Za-z0-9._/-]", "_", storage_key))
    try:
        parent = os.path.dirname(blob_path)
        os.makedirs(parent, exist_ok=True)
        with open(blob_path, "wb") as out:
            out.write(raw)
    except Exception:
        endiso = _iso()
        run["status"] = "failed"
        run["ended_at"] = endiso
        run["error_code"] = "CONFLICT"
        run["error_message"] = "Failed to persist blob content"
        run["updated_at"] = endiso
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return _err("CONFLICT", "Failed to persist blob content")

    # Create uploaded_files row
    created = _iso()
    frow = {
        "id": file_id,
        "workspace_id": ws.get("id"),
        "uploaded_by_key_id": key.get("id"),
        "original_filename": filename,
        "content_type": content_type,
        "size_bytes": size_bytes,
        "sha256_hex": sha256_hex,
        "storage_provider": storage_provider,
        "storage_bucket": storage_bucket,
        "storage_key": storage_key,
        "status": "uploaded",
        "error_message": None,
        "created_at": created,
        "updated_at": created,
    }
    uploaded_files.append(frow)

    # Link run to file, succeed
    endiso = _iso()
    run["uploaded_file_id"] = file_id
    run["status"] = "succeeded"
    run["ended_at"] = endiso
    run["response_json"] = {"file_id": file_id}
    run["updated_at"] = endiso
    run["meter_units"] = 0

    _touch_key_last_used(api_keys, key.get("id"))
    _save("uploaded_files.json", uploaded_files)
    _save("tool_runs.json", tool_runs)
    _save("api_keys.json", api_keys)

    return {"file_id": file_id}

def visualize_file(workspace_id, file_id, visualization_kind=None, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        if dt is None:
            dt = _now()
        if dt.tzinfo is None:
