        for r in tool_runs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            art = r.get("visualization_artifact")
            if isinstance(art, dict):
                b = art.get("bytes")
                if isinstance(b, int) and b >= 0:
