    if not isinstance(file_id, str) or not file_id.strip():
        return _err("VALIDATION_ERROR", "file_id must be a non-empty string")
    allowed_kinds = {"html", "svg", "png", "vega_lite", "json"}
    if visualization_kind is not None:
        if not isinstance(visualization_kind, str) or visualization_kind not in allowed_kinds:
            return _err("VALIDATION_ERROR", "visualization_kind is invalid", allowed=sorted(list(allowed_kinds)))
