        "api_key_id": key.get("id"),
        "tool_name": "visualize_file",
        "request_json": {"workspace_id": workspace_id, "file_id": file_id, "visualization_kind": visualization_kind},
        "uploaded_file_id": file_id,
        "dataset_id": None,
        "status": "queued",
        "started_at": None,
        "ended_at": None,
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "visualization_kind": kind,
        "visualization_artifact": None,
        "meter_units": 0,
        "created_at": nowiso,
        "updated_at": nowiso,
    }
