        run["status"] = "failed"
        run["ended_at"] = endiso
        run["error_code"] = "NOT_FOUND"
        run["error_message"] = "Uploaded file not found"
        run["updated_at"] = endiso
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return _err("NOT_FOUND", "Uploaded file not found", file_id=file_id)
    if frow.get("workspace_id") != ws.get("id"):
        endiso = _iso()
        run["status"] = "failed"
        run["ended_at"] = endiso
        run["error_code"] = "UNAUTHORIZED"
        run["error_message"] = "Cannot access uploaded file in another workspace"
        run["updated_at"] = endiso
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return _err("UNAUTHORIZED", "Cannot access file in another workspace", file_id=file_id)

    fstatus = frow.get("status")
    if fstatus in ("failed", "deleted"):
        endiso = _iso()
        run["status"] = "failed"
        run["ended_at"] = endiso
        run["error_code"] = "INVALID_TRANSITION"
        run["error_message"] = f"Cannot visualize file in status '{fstatus}'"
        run["updated_at"] = endiso
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return _err("INVALID_TRANSITION", "File cannot be visualized in its current status", status=fstatus)
    if fstatus not in ("ready", "scanned", "uploaded"):
        endiso = _iso()
        run["status"] = "failed"
        run["ended_at"] = endiso
        run["error_code"] = "VALIDATION_ERROR"
        run["error_message"] = f"Unknown file status '{fstatus}'"
        run["updated_at"] = endiso
        _touch_key_last_used(api_keys, key.get("id"))
        _save("tool_runs.json", tool_runs)
        _save("api_keys.json", api_keys)
        return _err("VALIDATION_ERROR", "Invalid file status on record", status=fstatus)

    # Quota: visualizations per day
    day = _utc_day()
    qmax = ws.get("quota_max_visualizations_per_day")
    if isinstance(qmax, int) and qmax >= 0:
        used = _count_succeeded_visualizations_today(ws.get("id"), tool_runs, day)
        if used >= qmax:
            endiso = _iso()
            run["status"] = "failed"
            run["ended_at"] = endiso
            run["error_code"] = "QUOTA_EXCEEDED"
            run["error_message"] = "Workspace visualization quota exceeded (quota_max_visualizations_per_day)"
            run["updated_at"] = endiso
            _touch_key_last_used(api_keys, key.get("id"))
            _save("tool_runs.json", tool_runs)
            _save("api_keys.json", api_keys)
            return _err("QUOTA_EXCEEDED", "Workspace visualization quota exceeded", rule="quota_max_visualizations_per_day", quota=qmax, day_utc=day)

