            _save("api_keys.json", api_keys)
            return _err("QUOTA_EXCEEDED", "Workspace storage quota exceeded", rule="quota_max_storage_bytes", quota=max_bytes, retained_bytes=retained, attempted_add_bytes=artifact_bytes)

    # Store artifact inline
    if kind == "html":
        payload = f"<html><body><h1>Visualization for {frow.get('original_filename') or file_id}</h1></body></html>"
        content_type = "text/html; charset=utf-8"
    elif kind == "svg":
        payload = "<svg xmlns='http://www.w3.org/2000/svg' width='200' height='60'><text x='10' y='35'>Tako SVG</text></svg>"
        content_type = "image/svg+xml"
    elif kind == "png":
        payload = {"note": "png bytes stored externally not implemented in offline mode"}
        content_type = "image/png"
    elif kind == "vega_lite":
        payload = {"$schema": "https://vega.github.io/schema/vega-lite/v5.json", "description": "Placeholder chart", "mark": "bar", "encoding": {}, "data": {"values": []}}
        content_type = "application/json"
    else:
        payload = {"type": "placeholder", "file_id": file_id}
        content_type = "application/json"

    artifact = {
        "storage_provider": "local",
        "bucket": None,
        "key": None,
        "bytes": artifact_bytes,
        "content_type": content_type,
        "payload": payload,
    }

    endiso = _iso()
    run["status"] = "succeeded"
    run["ended_at"] = endiso
    run["visualization_kind"] = kind
    run["visualization_artifact"] = artifact
    run["response_json"] = {"visualization_kind": kind, "visualization": payload}
    run["updated_at"] = endiso
    run["meter_units"] = 1

    _touch_key_last_used(api_keys, key.get("id"))
    _save("tool_runs.json", tool_runs)
    _save("api_keys.json", api_keys)

    return {"visualization_kind": kind, "visualization": payload}

