        ct = "image/png"
    elif kind == "vega_lite":
        payload = {"$schema": "https://vega.github.io/schema/vega-lite/v5.json", "description": "Placeholder dataset chart", "mark": "point", "encoding": {}, "data": {"values": []}}
        ct = "application/json"
    else:
        payload = {"type": "placeholder", "dataset_id": ds_id}
        ct = "application/json"

    artifact = {"storage_provider": "local", "bucket": None, "key": None, "bytes": artifact_bytes, "content_type": ct, "payload": payload}

    endiso = _iso()
    run["status"] = "succeeded"
    run["ended_at"] = endiso
    run["visualization_kind"] = kind
    run["visualization_artifact"] = artifact
    run["response_json"] = {"dataset_id": ds_id, "visualization_kind": kind, "visualization": payload}
    run["updated_at"] = endiso
    run["meter_units"] = 1

    _touch_key_last_used(api_keys, key.get("id"))
    _save("datasets.json", datasets)
    _save("tool_runs.json", tool_runs)
    _save("api_keys.json", api_keys)

    return {"dataset_id": ds_id, "visualization_kind": kind, "visualization": payload}

def get_tako_identity(api_key, **_extra):
    import json, os, datetime, time, base64, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validation
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    api_key = api_key.strip()

    # Resolve credential: match by id OR by client-visible plaintext value (never by hash compare)
    api_keys = _load("api_keys.json")
    key_row = None
    for r in api_keys:
        if r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        # Try matching against a stored client-visible field if present in the datastore (not specified, but may exist)
        for r in api_keys:
            if r.get("key") == api_key or r.get("api_key") == api_key or r.get("secret") == api_key:
                key_row = r
                break

    if key_row is None:
        return _err("UNAUTHORIZED", "API key is missing, invalid, or revoked.")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is missing, invalid, or revoked.", key_id=key_row.get("id"))

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found for API key.", workspace_id=key_row.get("workspace_id"))
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_id=ws.get("id"), status=ws.get("status"))

    # Compute current quota usage/consumption
    uploaded_files = _load("uploaded_files.json")
    tool_runs = _load("tool_runs.json")

    non_deleted_files = [f for f in uploaded_files if f.get("workspace_id") == ws.get("id") and f.get("status") != "deleted"]
    file_count = len(non_deleted_files)
    file_bytes = 0
    for f in non_deleted_files:
        try:
            sb = int(f.get("size_bytes", 0))
            if sb > 0:
                file_bytes += sb
        except Exception:
            pass

    # Visualization artifacts stored bytes (approx) from succeeded runs
    artifact_bytes = 0
    for tr in tool_runs:
        if tr.get("workspace_id") != ws.get("id"):
            continue
        if tr.get("status") != "succeeded":
            continue
        art = tr.get("visualization_artifact")
        if isinstance(art, dict):
            b = art.get("bytes")
            if isinstance(b, int) and b > 0:
                artifact_bytes += b
            elif isinstance(b, str):
                # attempt to parse numeric
                try:
                    bi = int(b)
                    if bi > 0:
                        artifact_bytes += bi
                except Exception:
                    pass

    total_retained_bytes = file_bytes + artifact_bytes

    # Daily succeeded visualization runs count (UTC day)
    def _utc_day(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            # Accept ISO with Z or offset
            s = ts.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).date().isoformat()
        except Exception:
            return None

    today = datetime.datetime.now(datetime.timezone.utc).date().isoformat()
    succeeded_visualizations_today = 0
    for tr in tool_runs:
        if tr.get("workspace_id") != ws.get("id"):
            continue
        if tr.get("status") != "succeeded":
            continue
        if tr.get("tool_name") not in ("visualize_file", "visualize_dataset"):
            continue
        day = _utc_day(tr.get("created_at") or tr.get("updated_at"))
        if day == today:
            succeeded_visualizations_today += 1

    # Update key last_used_at (real effect)
    updated = False
    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            updated = True
            break
    if updated:
        _save("api_keys.json", api_keys)

    # Log invocation as tool_runs row (business requirement applies to tool invocations set; still log for observability)
    # Since get_tako_identity is not in tool_runs.tool_name enum, store as search_tako with a tagged request,
    # preserving enum integrity and still capturing the call in request_json.
    tr_id = "tako_run_" + uuid.uuid4().hex
    run = {
        "id": tr_id,
        "workspace_id": ws.get("id"),
        "api_key_id": key_row.get("id"),
        "tool_name": "search_tako",
        "request_json": {"__endpoint__": "get_tako_identity", "api_key_id": key_row.get("id")},
        "uploaded_file_id": None,
        "dataset_id": None,
        "status": "succeeded",
        "started_at": now,
        "ended_at": now,
        "error_code": None,
        "error_message": None,
        "response_json": {"identity": True},
        "visualization_kind": None,
        "visualization_artifact": None,
        "meter_units": 0,
        "created_at": now,
        "updated_at": now,
    }
    tool_runs.append(run)
    _save("tool_runs.json", tool_runs)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "plan": ws.get("plan"),
            "status": ws.get("status"),
        },
        "api_key": {
            "id": key_row.get("id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "last_used_at": key_row.get("last_used_at"),
        },
        "scopes": ["*"],
        "quotas": {
            "max_files": ws.get("quota_max_files"),
            "max_storage_bytes": ws.get("quota_max_storage_bytes"),
            "max_visualizations_per_day": ws.get("quota_max_visualizations_per_day"),
        },
        "usage": {
            "retained_files": file_count,
            "retained_storage_bytes": total_retained_bytes,
            "succeeded_visualizations_today_utc": succeeded_visualizations_today,
        },
        "meta": {"latency_ms": latency_ms},
    }

def list_uploaded_files(workspace_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validate
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string.")
    workspace_id = workspace_id.strip()

    allowed_status = {"uploaded", "scanned", "ready", "failed", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(list(allowed_status)))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

    start_after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        # cursor format: base64url(json={"after_id":...})
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            start_after_id = obj.get("after_id")
            if not isinstance(start_after_id, str) or not start_after_id:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Auth is ambient: choose an active workspace that can serve (must exist)
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_id=workspace_id, status=ws.get("status"))

    uploaded_files = _load("uploaded_files.json")

    # Filter rows for workspace and optional status
    rows = [r for r in uploaded_files if r.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # Order by newest first: created_at desc, then id desc as tie-breaker
    def _dt(s):
        if not isinstance(s, str) or not s:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows.sort(key=lambda r: (_dt(r.get("created_at")), str(r.get("id") or "")), reverse=True)

    # Apply cursor by id position in ordered list
    if start_after_id is not None:
        idx = None
        for i, r in enumerate(rows):
            if r.get("id") == start_after_id:
                idx = i
                break
        if idx is not None:
            rows = rows[idx + 1 :]
        else:
            # Cursor does not match any row in this result set -> treat as empty page
            rows = []

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        after_id = page[-1].get("id")
        payload = json.dumps({"after_id": after_id}, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Record call in tool_runs (use search_tako enum with endpoint tag to preserve schema)
    tool_runs = _load("tool_runs.json")
    tr_id = "tako_run_" + uuid.uuid4().hex
    run = {
        "id": tr_id,
        "workspace_id": workspace_id,
        "api_key_id": None,
        "tool_name": "search_tako",
        "request_json": {
            "__endpoint__": "list_uploaded_files",
            "workspace_id": workspace_id,
            "status": status,
            "limit": limit,
            "cursor": cursor,
        },
        "uploaded_file_id": None,
        "dataset_id": None,
        "status": "succeeded",
        "started_at": now,
        "ended_at": now,
        "error_code": None,
        "error_message": None,
        "response_json": {"count": len(page)},
        "visualization_kind": None,
        "visualization_artifact": None,
        "meter_units": 0,
        "created_at": now,
        "updated_at": now,
    }
    tool_runs.append(run)
    _save("tool_runs.json", tool_runs)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": page,
        "meta": {
            "workspace_id": workspace_id,
            "limit": limit,
            "total_in_page_scope": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
        },
    }

