def update_uploaded_file(workspace_id, file_id, status=None, error_message=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        dt = dt or _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(tool_runs, api_key_id, ws_id, status, response_json=None, error_code=None, error_message=None, uploaded_file_id=None):
        # Not a vendor tool, but backend requires observable dynamics for every call.
        # We record as a 'search_tako' run because this surface has no dedicated admin tool name.
        rid = "tako_run_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        now = _iso()
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "tool_name": "search_tako",
            "request_json": {
                "endpoint": "update_uploaded_file",
                "workspace_id": workspace_id,
                "file_id": file_id,
                "status": status if status is not None else None,
                "error_message": error_message if error_message is not None else None,
            },
            "uploaded_file_id": uploaded_file_id,
            "dataset_id": None,
            "status": "succeeded" if status == "succeeded" else "failed",
            "started_at": now,
            "ended_at": now,
            "error_code": error_code,
            "error_message": error_message,
            "response_json": response_json,
            "visualization_kind": None,
            "visualization_artifact": None,
            "meter_units": 0,
            "created_at": now,
            "updated_at": now,
        }
        tool_runs.append(row)
        return row

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string", workspace_id=workspace_id)
    if not isinstance(file_id, str) or not file_id:
        return _err("VALIDATION_ERROR", "file_id must be a non-empty string", file_id=file_id)

    allowed_status = {"uploaded", "scanned", "ready", "failed", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: uploaded, scanned, ready, failed, deleted", status=status)
    if error_message is not None and not isinstance(error_message, str):
        return _err("VALIDATION_ERROR", "error_message must be a string when provided", error_message=error_message)

    # Load datastore
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    uploaded_files = _load("uploaded_files.json")
    tool_runs = _load("tool_runs.json")

    # Resolve workspace & ambient authentication: pick an active key for this workspace (if any),
    # but do not fail merely because the signature carries no credential; UNAUTHORIZED only if
    # no workable active key exists for an accessible workspace.
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        # record call best-effort (no workspace to attach)
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    if ws.get("status") != "active":
        # workspace exists but is not accessible for mutations
        _log(tool_runs, None, workspace_id, "failed", response_json=None, error_code="WORKSPACE_NOT_ACTIVE",
             error_message=f"Workspace status '{ws.get('status')}' does not allow updates", uploaded_file_id=None)
        _save("tool_runs.json", tool_runs)
        return _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=workspace_id, status=ws.get("status"))

    candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"]
    # As per business rule: operations require an active api key context; if none exist, refuse.
    if not candidate_keys:
        _log(tool_runs, None, workspace_id, "failed", response_json=None, error_code="NO_ACTIVE_KEY",
             error_message="No active API key available for this workspace", uploaded_file_id=None)
        _save("tool_runs.json", tool_runs)
        return _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=workspace_id)

    # Choose most recently used/created key
    def _k_sort(k):
        lu = _parse_dt(k.get("last_used_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        ca = _parse_dt(k.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (lu, ca, k.get("id") or "")
    candidate_keys.sort(key=_k_sort, reverse=True)
    key = candidate_keys[0]

    # Find file and enforce FK + same-workspace rule
    fidx = None
    frow = None
    for i, r in enumerate(uploaded_files):
        if isinstance(r, dict) and r.get("id") == file_id:
            fidx, frow = i, r
            break
    if not frow:
        _log(tool_runs, key.get("id"), workspace_id, "failed", response_json=None, error_code="FILE_NOT_FOUND",
             error_message="Uploaded file not found", uploaded_file_id=None)
        _save("tool_runs.json", tool_runs)
        return _err("NOT_FOUND", "Uploaded file not found", file_id=file_id)

    if frow.get("workspace_id") != workspace_id:
        _log(tool_runs, key.get("id"), workspace_id, "failed", response_json=None, error_code="CROSS_WORKSPACE",
             error_message="File does not belong to the specified workspace", uploaded_file_id=file_id)
        _save("tool_runs.json", tool_runs)
        return _err("UNAUTHORIZED", "File does not belong to the specified workspace", workspace_id=workspace_id, file_id=file_id)

    # If nothing to update, refuse (no success without effect)
    if status is None and error_message is None:
        _log(tool_runs, key.get("id"), workspace_id, "failed", response_json=None, error_code="NO_CHANGES",
             error_message="No mutable fields provided to update", uploaded_file_id=file_id)
        _save("tool_runs.json", tool_runs)
        return _err("VALIDATION_ERROR", "No mutable fields provided to update")

    # Enforce lifecycle transitions
    transitions = {
        "uploaded": ["scanned", "failed", "deleted"],
        "scanned": ["ready", "failed", "deleted"],
        "ready": ["deleted"],
        "failed": ["deleted"],
        "deleted": [],
    }

    old_status = frow.get("status")
    if old_status not in transitions:
        _log(tool_runs, key.get("id"), workspace_id, "failed", response_json=None, error_code="BAD_STATE",
             error_message="File is in an unknown lifecycle state", uploaded_file_id=file_id)
        _save("tool_runs.json", tool_runs)
        return _err("CONFLICT", "File is in an unknown lifecycle state", status=old_status)

    # Determine requested changes
    new_status = old_status if status is None else status

    # Allow setting/clearing error_message independent of status transitions:
    # Real-world backend may store operator notes even if status isn't 'failed'.
    # Business rule only implies it is used for failures, but does not forbid storing it otherwise.
    # However, do enforce: if transitioning to 'failed', a non-empty error_message is required.
    if status is not None and new_status != old_status:
        if new_status not in transitions.get(old_status, []):
            _log(tool_runs, key.get("id"), workspace_id, "failed", response_json=None, error_code="INVALID_TRANSITION",
                 error_message=f"Invalid status transition for uploaded_files: {old_status} -> {new_status}", uploaded_file_id=file_id)
            _save("tool_runs.json", tool_runs)
            return _err("INVALID_TRANSITION", f"Invalid status transition: {old_status} -> {new_status}", from_status=old_status, to_status=new_status)

    if status is not None and new_status == "failed":
        if error_message is None or (isinstance(error_message, str) and error_message.strip() == ""):
            _log(tool_runs, key.get("id"), workspace_id, "failed", response_json=None, error_code="MISSING_ERROR_MESSAGE",
                 error_message="error_message is required when setting status='failed'", uploaded_file_id=file_id)
            _save("tool_runs.json", tool_runs)
            return _err("VALIDATION_ERROR", "error_message is required when setting status='failed'")

    # Apply changes and ensure there is an effect
    changed = False
    now = _iso()

    if status is not None and new_status != old_status:
        uploaded_files[fidx]["status"] = new_status
        changed = True

    if error_message is not None:
        # write-through as provided (can be used as operator note)
        uploaded_files[fidx]["error_message"] = error_message
        # effect only if different
        if frow.get("error_message") != error_message:
            changed = True

    if not changed:
        _log(tool_runs, key.get("id"), workspace_id, "failed", response_json=None, error_code="NO_EFFECT",
             error_message="Update matched the file but made no changes", uploaded_file_id=file_id)
        _save("tool_runs.json", tool_runs)
        return _err("CONFLICT", "Update made no changes", file_id=file_id)

    uploaded_files[fidx]["updated_at"] = now

    # Update key last_used_at
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            api_keys[i]["last_used_at"] = now
            api_keys[i]["updated_at"] = api_keys[i].get("updated_at") or now
            break

    # Persist
    _save("uploaded_files.json", uploaded_files)
    _save("api_keys.json", api_keys)

    # Log tool run record
    resp = uploaded_files[fidx]
    _log(tool_runs, key.get("id"), workspace_id, "succeeded", response_json={"uploaded_file": resp}, uploaded_file_id=file_id)
    _save("tool_runs.json", tool_runs)

    return {"uploaded_file": resp}

def list_tool_runs(workspace_id, tool_name=None, status=None, uploaded_file_id=None, dataset_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        if dt is None:
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict) or obj.get("v") != 1:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        before = obj.get("before")
        rid = obj.get("id")
        if not isinstance(before, str) or not isinstance(rid, str):
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if _parse_dt(before) is None:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return {"before": before, "id": rid}

    def _make_cursor(before, rid):
        payload = {"v": 1, "before": before, "id": rid}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _resolve_auth(workspace_id, api_keys, workspaces):
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            return None, _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        if ws.get("status") != "active":
            return None, _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=workspace_id, status=ws.get("status"))
        candidates = [k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=workspace_id)
        return {"workspace": ws, "api_key": candidates[0]}, None

    def _touch_key_last_used(api_keys, key_id):
        nowiso = _iso()
        for k in api_keys:
            if k.get("id") == key_id:
                k["last_used_at"] = nowiso
                k["updated_at"] = nowiso
                return True
        return False

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if tool_name is not None:
        if not isinstance(tool_name, str):
            return _err("VALIDATION_ERROR", "tool_name must be a string")
        if tool_name not in {"search_tako", "upload_file_to_visualize", "visualize_file", "visualize_dataset"}:
            return _err("VALIDATION_ERROR", "Invalid tool_name")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in {"queued", "running", "succeeded", "failed", "cancelled"}:
            return _err("VALIDATION_ERROR", "Invalid status")
    if uploaded_file_id is not None and (not isinstance(uploaded_file_id, str) or not uploaded_file_id.strip()):
        return _err("VALIDATION_ERROR", "uploaded_file_id must be a non-empty string when provided")
    if dataset_id is not None and (not isinstance(dataset_id, str) or not dataset_id.strip()):
        return _err("VALIDATION_ERROR", "dataset_id must be a non-empty string when provided")
    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_i = limit

    curinfo = None
    if cursor is not None:
        curinfo = _parse_cursor(cursor)
        if isinstance(curinfo, dict) and "error" in curinfo:
            return curinfo

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tool_runs = _load("tool_runs.json")

    auth, auth_err = _resolve_auth(workspace_id.strip(), api_keys, workspaces)
    if auth_err:
        return auth_err
    ws = auth["workspace"]
    key = auth["api_key"]

    # Filter
    rows = []
    for r in tool_runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws.get("id"):
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if uploaded_file_id is not None and r.get("uploaded_file_id") != uploaded_file_id:
            continue
        if dataset_id is not None and r.get("dataset_id") != dataset_id:
            continue
        rows.append(r)

    # Sort newest first by created_at then id
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor boundary
    if curinfo:
        bdt = _parse_dt(curinfo["before"]) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        bid = str(curinfo["id"])
        filtered = []
        for r in rows:
            dt = _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            rid = str(r.get("id") or "")
            if dt < bdt:
                filtered.append(r)
            elif dt == bdt and rid < bid:
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit_i]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _make_cursor(last.get("created_at"), last.get("id"))

    _touch_key_last_used(api_keys, key.get("id"))
    _save("api_keys.json", api_keys)

    return {"tool_runs": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def cancel_tool_run(workspace_id, tool_run_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0388000" if __import__("os").path.isdir("./environment_mix/0388000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        dt = dt or _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(tool_runs, api_key_id, ws_id, ok, response_json=None, error_code=None, error_message=None, run_id=None):
        rid = "tako_run_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        now = _iso()
        row = {
            "id": rid,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "tool_name": "search_tako",
            "request_json": {"endpoint": "cancel_tool_run", "workspace_id": workspace_id, "tool_run_id": tool_run_id},
            "uploaded_file_id": None,
            "dataset_id": None,
            "status": "succeeded" if ok else "failed",
            "started_at": now,
            "ended_at": now,
            "error_code": error_code,
            "error_message": error_message,
            "response_json": response_json,
            "visualization_kind": None,
            "visualization_artifact": None,
            "meter_units": 0,
            "created_at": now,
            "updated_at": now,
        }
        tool_runs.append(row)
        return row

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string", workspace_id=workspace_id)
    if not isinstance(tool_run_id, str) or not tool_run_id:
        return _err("VALIDATION_ERROR", "tool_run_id must be a non-empty string", tool_run_id=tool_run_id)

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tool_runs = _load("tool_runs.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    if ws.get("status") != "active":
        _log(tool_runs, None, workspace_id, False, response_json=None, error_code="WORKSPACE_NOT_ACTIVE",
             error_message=f"Workspace status '{ws.get('status')}' does not allow cancellation", run_id=tool_run_id)
        _save("tool_runs.json", tool_runs)
        return _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=workspace_id, status=ws.get("status"))

    candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"]
    if not candidate_keys:
        _log(tool_runs, None, workspace_id, False, response_json=None, error_code="NO_ACTIVE_KEY",
             error_message="No active API key available for this workspace", run_id=tool_run_id)
        _save("tool_runs.json", tool_runs)
        return _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=workspace_id)

    def _k_sort(k):
        lu = _parse_dt(k.get("last_used_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        ca = _parse_dt(k.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (lu, ca, k.get("id") or "")
    candidate_keys.sort(key=_k_sort, reverse=True)
    key = candidate_keys[0]

    # Find tool run (must be a real tool_runs row, not the workspace id)
    ridx = None
    run = None
    for i, r in enumerate(tool_runs):
        if isinstance(r, dict) and r.get("id") == tool_run_id:
            ridx, run = i, r
            break
    if not run:
        _log(tool_runs, key.get("id"), workspace_id, False, response_json=None, error_code="RUN_NOT_FOUND",
             error_message="Tool run not found", run_id=tool_run_id)
        _save("tool_runs.json", tool_runs)
        return _err("NOT_FOUND", "Tool run not found", tool_run_id=tool_run_id)

    if run.get("workspace_id") != workspace_id:
        _log(tool_runs, key.get("id"), workspace_id, False, response_json=None, error_code="CROSS_WORKSPACE",
             error_message="Tool run does not belong to the specified workspace", run_id=tool_run_id)
        _save("tool_runs.json", tool_runs)
        return _err("UNAUTHORIZED", "Tool run does not belong to the specified workspace", workspace_id=workspace_id, tool_run_id=tool_run_id)

    transitions = {
        "queued": ["running", "cancelled"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": [],
    }

    cur = run.get("status")
    if cur not in transitions:
        _log(tool_runs, key.get("id"), workspace_id, False, response_json=None, error_code="BAD_STATE",
             error_message="Tool run is in an unknown lifecycle state", run_id=tool_run_id)
        _save("tool_runs.json", tool_runs)
        return _err("CONFLICT", "Tool run is in an unknown lifecycle state", status=cur)

    if "cancelled" not in transitions.get(cur, []):
        _log(tool_runs, key.get("id"), workspace_id, False, response_json=None, error_code="INVALID_TRANSITION",
             error_message=f"Cannot cancel a tool run in status '{cur}'", run_id=tool_run_id)
        _save("tool_runs.json", tool_runs)
        return _err("INVALID_TRANSITION", f"Cannot cancel a tool run in status '{cur}'", from_status=cur, to_status="cancelled")

    now = _iso()
    # Apply transition
    tool_runs[ridx]["status"] = "cancelled"
    # Ensure started_at exists if it was running; if queued, started_at can remain null.
    if cur == "running" and not tool_runs[ridx].get("started_at"):
        tool_runs[ridx]["started_at"] = now
    tool_runs[ridx]["ended_at"] = now
    tool_runs[ridx]["updated_at"] = now
    tool_runs[ridx]["error_code"] = tool_runs[ridx].get("error_code")
    tool_runs[ridx]["error_message"] = tool_runs[ridx].get("error_message")

    # Update key last_used_at
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            api_keys[i]["last_used_at"] = now
            api_keys[i]["updated_at"] = api_keys[i].get("updated_at") or now
            break

    _save("tool_runs.json", tool_runs)
    _save("api_keys.json", api_keys)

    # Record call
    _log(tool_runs, key.get("id"), workspace_id, True, response_json={"tool_run": tool_runs[ridx]}, run_id=tool_run_id)
    _save("tool_runs.json", tool_runs)

    return {"tool_run": tool_runs[ridx]}
